tinymce.PluginManager.add('ifbq_svg', function(editor, url) {
	
	CurrVarName = (CurrVarName) ? CurrVarName :'' ;
	editor.ui.registry.addButton('ifbqsvg', {
		text: 'Interaktiv SVG Bild',
		icon: 'table',
		id: 'ifbq_interaktivsvg',
		class: 'ifbqsvg',
        tooltip:'Interaktiv SVG-Bild hinzufügen',
		stateSelector:"img .ifbqsvg",
		onAction: ShowSvgSettings
	});
});
